export interface ContextRelatedEntityDto {
    /**
     * Application entity ID.
     * @type {string}
     * @memberof ContextRelatedEntityDto
     */
    'entityId': string;
    /**
     * Entity type (e.g. TASK, PLAN, DESIGN_DOC).
     * @type {string}
     * @memberof ContextRelatedEntityDto
     */
    'entityType': string;
    /**
     * Human-readable name or title of the entity.
     * @type {string}
     * @memberof ContextRelatedEntityDto
     */
    'displayName': string;
    /**
     * Current status of the entity, if available.
     * @type {string}
     * @memberof ContextRelatedEntityDto
     */
    'status'?: string;
    /**
     * 
     * @type {RelationshipValue}
     * @memberof ContextRelatedEntityDto
     */
    'relationship': RelationshipValue;
    /**
     * Ordered path from the seed to this entity when reached through an excluded pivot (e.g. a parent feature). Empty/absent for direct one-hop relationships. 
     * @type {Array<RelatedEntityViaDto>}
     * @memberof ContextRelatedEntityDto
     */
    'via'?: Array<RelatedEntityViaDto>;
    /**
     * 
     * @type {EdgeSource}
     * @memberof ContextRelatedEntityDto
     */
    'source'?: EdgeSource;
    /**
     * Natural language rationale recorded on create_edge. Present only for agent-authored relationships; absent for system-graph relationships. 
     * @type {string}
     * @memberof ContextRelatedEntityDto
     */
    'reasoning'?: string;
    /**
     * Work-item type key for TASK entries (STANDARD, BUG, FEATURE, GOAL, or a project-registered custom key). Present only when entityType is TASK; absent for all other entity types. 
     * @type {string}
     * @memberof ContextRelatedEntityDto
     */
    'taskType'?: string;
}


