/**
 * Stable safe denial. Responses reveal no canonical payload, assertion bytes, signature, credential existence, or secret material.
 * @export
 * @enum {string}
 */

export const ControllerAuthorizationDenialReason = {
    MachineNotReady: 'MACHINE_NOT_READY',
    MachineRevoked: 'MACHINE_REVOKED',
    ControllerNotActive: 'CONTROLLER_NOT_ACTIVE',
    AuthorizationNotFound: 'AUTHORIZATION_NOT_FOUND',
    AuthorizationExpired: 'AUTHORIZATION_EXPIRED',
    AuthorizationAlreadyConsumed: 'AUTHORIZATION_ALREADY_CONSUMED',
    CredentialMismatch: 'CREDENTIAL_MISMATCH',
    ChallengeMismatch: 'CHALLENGE_MISMATCH',
    OriginMismatch: 'ORIGIN_MISMATCH',
    RpIdMismatch: 'RP_ID_MISMATCH',
    UserPresenceRequired: 'USER_PRESENCE_REQUIRED',
    UserVerificationRequired: 'USER_VERIFICATION_REQUIRED',
    SignatureInvalid: 'SIGNATURE_INVALID',
    ActionMismatch: 'ACTION_MISMATCH',
    PayloadHashMismatch: 'PAYLOAD_HASH_MISMATCH',
    TargetMismatch: 'TARGET_MISMATCH',
    GrantNotActive: 'GRANT_NOT_ACTIVE',
    GrantScopeMismatch: 'GRANT_SCOPE_MISMATCH',
    ReplayDetected: 'REPLAY_DETECTED'
} as const;

export type ControllerAuthorizationDenialReason = typeof ControllerAuthorizationDenialReason[keyof typeof ControllerAuthorizationDenialReason];


