/**
 * A task discovered via agent-authored topology edges, hydrated with content (description, acceptance criteria) for assessment. Each entry represents a single directed edge between the queried entity and the dependent task. 
 * @export
 * @interface DependentTaskDto
 */
export interface DependentTaskDto {
    /**
     * The dependent task\'s ID
     * @type {string}
     * @memberof DependentTaskDto
     */
    'entityId': string;
    /**
     * Always \"TASK\" for dependent task resolution
     * @type {string}
     * @memberof DependentTaskDto
     */
    'entityType': string;
    /**
     * The dependent task\'s name
     * @type {string}
     * @memberof DependentTaskDto
     */
    'displayName': string;
    /**
     * Current status of the dependent task
     * @type {string}
     * @memberof DependentTaskDto
     */
    'status': string;
    /**
     * 
     * @type {AgentEdgeType}
     * @memberof DependentTaskDto
     */
    'relationshipType': AgentEdgeType;
    /**
     * Whether the edge goes from the queried entity to the dependent task (outbound) or from the dependent task to the queried entity (inbound). 
     * @type {string}
     * @memberof DependentTaskDto
     */
    'direction': DependentTaskDtoDirectionEnum;
    /**
     * The dependent task\'s description content (materialized markdown). Null when the task has no description section. 
     * @type {string}
     * @memberof DependentTaskDto
     */
    'description'?: string | null;
    /**
     * The dependent task\'s acceptance criteria content (materialized markdown). Null when the task has no acceptance criteria section. 
     * @type {string}
     * @memberof DependentTaskDto
     */
    'acceptanceCriteria'?: string | null;
    /**
     * Natural language rationale for why this edge exists, authored by the agent that created the relationship. 
     * @type {string}
     * @memberof DependentTaskDto
     */
    'edgeReasoning': string;
}

export const DependentTaskDtoDirectionEnum = {
    Outbound: 'outbound',
    Inbound: 'inbound'
} as const;

export type DependentTaskDtoDirectionEnum = typeof DependentTaskDtoDirectionEnum[keyof typeof DependentTaskDtoDirectionEnum];

