/**
 * An entity\'s content body — its materialized sections plus work-tracking metadata. Returned on get_context for TASK and DESIGN_DOC seeds. Plan and Stage work items use TASK content. The status / priority / assigneeId / dueDate fields are task-shaped: they are absent for content sourced from a design doc, which has no such fields, and are likewise absent for non-status-bearing work-item types (FEATURE, GOAL), whose state is read from links and tasks rather than stored. Only status-bearing types (STANDARD, BUG) carry all four. 
 * @export
 * @interface EntityContentDto
 */
export interface EntityContentDto {
    /**
     * Materialized section content keyed by section key (e.g. description, acceptanceCriteria, requirements). Values are each section\'s materialized markdown. Empty object when the entity has no sections. 
     * @type {{ [key: string]: string; }}
     * @memberof EntityContentDto
     */
    'sections': { [key: string]: string; };
    /**
     * Current work status of the entity. A WorkStatus for task-backed content, a design-doc status string for design-doc content, or a PlanStepStatus for un-backed step content. Absent for non-status-bearing work-item types (FEATURE, GOAL). 
     * @type {string}
     * @memberof EntityContentDto
     */
    'status'?: string;
    /**
     * Priority of the backing task (LOW / MEDIUM / HIGH / CRITICAL). Null when the task has no priority set; absent for content with no priority concept (design docs, un-backed steps) and for non-status-bearing work-item types (FEATURE, GOAL). 
     * @type {string}
     * @memberof EntityContentDto
     */
    'priority'?: string | null;
    /**
     * User the backing task is assigned to. Null when unassigned; absent for content with no assignee concept (design docs, un-backed steps) and for non-status-bearing work-item types (FEATURE, GOAL). 
     * @type {string}
     * @memberof EntityContentDto
     */
    'assigneeId'?: string | null;
    /**
     * When the backing task is due (ISO 8601). Null when no due date is set; absent for content with no due-date concept (design docs, un-backed steps) and for non-status-bearing work-item types (FEATURE, GOAL). 
     * @type {string}
     * @memberof EntityContentDto
     */
    'dueDate'?: string | null;
    /**
     * 
     * @type {FeatureRequirementsSection}
     * @memberof EntityContentDto
     */
    'requirementsSection'?: FeatureRequirementsSection;
}
/**
 * Unified context for any entity, combining proposal lineage, available MCP tools, and creation metadata. Returned by the entity context endpoint to power contextual menus and lineage display. 
 * @export
 * @interface EntityContextDto
 */
export interface EntityContextDto {
    /**
     * The entity\'s unique identifier
     * @type {string}
     * @memberof EntityContextDto
     */
    'entityId': string;
    /**
     * 
     * @type {EntityType}
     * @memberof EntityContextDto
     */
    'entityType': EntityType;
    /**
     * Persisted, resolved work-item type key for TASK seeds (GOAL, STANDARD, BUG, FEATURE, or a project-defined key). Absent for non-TASK seeds. 
     * @type {string}
     * @memberof EntityContextDto
     */
    'taskType'?: string;
    /**
     * Human-readable name or title of the entity, resolved from the entity\'s primary name field (e.g. name for tasks, title for plans). 
     * @type {string}
     * @memberof EntityContextDto
     */
    'displayName': string;
    /**
     * When the entity was originally created (ISO 8601)
     * @type {string}
     * @memberof EntityContextDto
     */
    'createdAt': string;
    /**
     * ID of the proposal that originally created this entity, if one exists. Derived from the earliest CREATE-action proposal targeting this entity. 
     * @type {string}
     * @memberof EntityContextDto
     */
    'creatingProposalId'?: string;
    /**
     * 
     * @type {ProposalDetail}
     * @memberof EntityContextDto
     */
    'proposalDetail'?: ProposalDetail;
    /**
     * True when the bounded summary omits older visible proposal history. False for full detail and when all visible proposals fit the summary. 
     * @type {boolean}
     * @memberof EntityContextDto
     */
    'olderProposalsOmitted'?: boolean;
    /**
     * Proposals that created or modified this entity, in reverse chronological order. Summary mode returns at most four compact entries; full mode returns authoritative ProposalResponseDto entries. Empty array if no proposals exist. 
     * @type {Array<EntityContextDtoProposalsInner>}
     * @memberof EntityContextDto
     */
    'proposals'?: Array<EntityContextDtoProposalsInner>;
    /**
     * MCP tools available in this entity\'s context menu. Each tool declares its targetEntityType, which may differ from the entity being viewed (e.g., create_task targets TASK but appears when viewing an INITIATIVE). 
     * @type {Array<AvailableMcpToolDto>}
     * @memberof EntityContextDto
     */
    'availableMcpTools'?: Array<AvailableMcpToolDto>;
}


