/**
 * A FEATURE-typed task related to the seed entity in the product hierarchy. Two shapes share this object, discriminated by relationshipType: - relationshipType: \'structural\' — the entry came from the parent/sibling/   descendant tree walk. Carries `relationship` (ancestor/sibling/   descendant) and `distance` (hop count). `direction`, `parentTaskId`,   and `reasoning` are absent.  - relationshipType: \'RELATED_TO\' | \'DEPENDS_ON\' | \'DERIVES_FROM\' |   \'SUPERSEDES\' | \'CONTRADICTS\' | \'EVOLVES\' | \'PROPOSED_TOGETHER\' —   the entry came from an agent-authored or system-emitted edge between   two FEATURE tasks. PROPOSED_TOGETHER entries are symmetric and   carry `source: system`; the remaining types are agent-   authored. Carries `direction`   (outbound when the seed is the edge source, inbound when the seed is   the edge target),   `parentTaskId` (the connected feature\'s parent task ID, nullable for   roots), and `reasoning` (the edge\'s natural-language rationale).   `relationship` and `distance` are absent because typed-edge entries   live outside the structural tree.  `BLOCKS` agent edges are intentionally excluded. Direction values match `DependentTaskDto.direction` (outbound/inbound) so consumers can reuse the same vocabulary across agent-edge surfaces. 
 * @export
 * @interface FeatureHierarchyEntryDto
 */
export interface FeatureHierarchyEntryDto {
    /**
     * Feature task ID
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'id': string;
    /**
     * Feature task name
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'name': string;
    /**
     * 
     * @type {FeatureTag}
     * @memberof FeatureHierarchyEntryDto
     */
    'tag'?: FeatureTag;
    /**
     * Feature description truncated to 225 characters (materialized from its description section). Null when the feature has no description section. Compare with descriptionFullLength to determine whether the full text was returned or truncated. 
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'description'?: string | null;
    /**
     * Total character count of the untruncated description. Null when the feature has no description section. When equal to description.length, the full text is present; when greater, a batched get_full_entity({ entities: [{ entityType: \'FEATURE\', entityId }] }) call is needed for the complete content. 
     * @type {number}
     * @memberof FeatureHierarchyEntryDto
     */
    'descriptionFullLength'?: number | null;
    /**
     * Discriminator for how this feature is connected to the seed. `structural` denotes a parent/sibling/descendant entry from the tree walk. The remaining values mirror the shared AgentEdgeType (see schemas/agent-edges.yaml#/AgentEdgeType) and represent agent-authored or system-emitted edge types between two FEATURE tasks. PROPOSED_TOGETHER is symmetric and is always paired with `source: system` (see schemas/agent-edges.yaml#/EdgeSource) on the underlying edge. 
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'relationshipType': FeatureHierarchyEntryDtoRelationshipTypeEnum;
    /**
     * 
     * @type {EdgeSource}
     * @memberof FeatureHierarchyEntryDto
     */
    'source'?: EdgeSource;
    /**
     * Structural position relative to the queried entity. Present only when relationshipType is `structural`. ancestor: feature is above this entity in the hierarchy. descendant: feature is below this entity in the hierarchy. sibling: feature shares the same direct parent. 
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'relationship'?: FeatureHierarchyEntryDtoRelationshipEnum;
    /**
     * Number of hops from the entity (minimum 1). Present only when relationshipType is `structural`. 
     * @type {number}
     * @memberof FeatureHierarchyEntryDto
     */
    'distance'?: number;
    /**
     * Edge direction relative to the seed feature. `outbound` when the seed is the edge source; `inbound` when the seed is the edge target. Present only on typed-edge entries. Mirrors the vocabulary used by DependentTaskDto.direction. 
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'direction'?: FeatureHierarchyEntryDtoDirectionEnum;
    /**
     * Parent task ID of the connected feature (null when the connected feature is a root). Present only on typed-edge entries so consumers can place the related feature within the broader feature tree without another lookup. 
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'parentTaskId'?: string | null;
    /**
     * Natural-language rationale recorded on the agent edge. Present only on typed-edge entries. 
     * @type {string}
     * @memberof FeatureHierarchyEntryDto
     */
    'reasoning'?: string;
}

export const FeatureHierarchyEntryDtoRelationshipTypeEnum = {
    Structural: 'structural',
    RelatedTo: 'RELATED_TO',
    DependsOn: 'DEPENDS_ON',
    DerivesFrom: 'DERIVES_FROM',
    Supersedes: 'SUPERSEDES',
    Contradicts: 'CONTRADICTS',
    Evolves: 'EVOLVES',
    ProposedTogether: 'PROPOSED_TOGETHER'
} as const;

export type FeatureHierarchyEntryDtoRelationshipTypeEnum = typeof FeatureHierarchyEntryDtoRelationshipTypeEnum[keyof typeof FeatureHierarchyEntryDtoRelationshipTypeEnum];
export const FeatureHierarchyEntryDtoRelationshipEnum = {
    Ancestor: 'ancestor',
    Descendant: 'descendant',
    Sibling: 'sibling'
} as const;

export type FeatureHierarchyEntryDtoRelationshipEnum = typeof FeatureHierarchyEntryDtoRelationshipEnum[keyof typeof FeatureHierarchyEntryDtoRelationshipEnum];
export const FeatureHierarchyEntryDtoDirectionEnum = {
    Outbound: 'outbound',
    Inbound: 'inbound'
} as const;

export type FeatureHierarchyEntryDtoDirectionEnum = typeof FeatureHierarchyEntryDtoDirectionEnum[keyof typeof FeatureHierarchyEntryDtoDirectionEnum];

