export interface FeatureListRefinement {
    /**
     * Section-scoped feedback keyed by top-level node id (the `id` values emitted in `FeatureListSystemMessageData.topLevels`). Empty-string values indicate the user left that section blank.
     * @type {{ [key: string]: string; }}
     * @memberof FeatureListRefinement
     */
    'sections': { [key: string]: string; };
    /**
     * Cross-cutting or structural feedback that applies to the entire proposal (merging top-levels, splitting, rebucketing). Empty string when the user did not provide overall feedback.
     * @type {string}
     * @memberof FeatureListRefinement
     */
    'overall': string;
}
/**
 * 
 * @export
 * @interface FeatureListSystemMessageData
 */
export interface FeatureListSystemMessageData extends SystemMessageData {
    /**
     * ID of the conversational flow this message belongs to
     * @type {string}
     * @memberof FeatureListSystemMessageData
     */
    'flowId'?: string;
    /**
     * ID of the specific node/step within the flow
     * @type {string}
     * @memberof FeatureListSystemMessageData
     */
    'nodeId'?: string;
    /**
     * Whether this message should be included in RAG retrieval
     * @type {boolean}
     * @memberof FeatureListSystemMessageData
     */
    'ragEnabled'?: boolean;
    /**
     * Title or header for this conversation step
     * @type {string}
     * @memberof FeatureListSystemMessageData
     */
    'title'?: string;
    /**
     * Intent detected by the LLM
     * @type {string}
     * @memberof FeatureListSystemMessageData
     */
    'detectedIntent': string;
    /**
     * Confidence score for the detected intent
     * @type {number}
     * @memberof FeatureListSystemMessageData
     */
    'intentConfidence': number;
    /**
     * UUIDs of the DRAFT top-level feature proposals created for this review. Matches the `id` values in `topLevels`.
     * @type {Array<string>}
     * @memberof FeatureListSystemMessageData
     */
    'generatedProposalIds': Array<string>;
    /**
     * Short narrative describing the shape of the proposed feature set (e.g. \"your project delivers two things: Widgets and Widget Factory\"). Generated together with the hierarchy so wording reflects the actual bucketing.
     * @type {string}
     * @memberof FeatureListSystemMessageData
     */
    'narrative': string;
    /**
     * Ordered list of top-level feature proposals. Each carries its own id plus a non-empty `children` array so the frontend can render the hierarchy without reconstructing structure.
     * @type {Array<FeatureListProposalNode>}
     * @memberof FeatureListSystemMessageData
     */
    'topLevels': Array<FeatureListProposalNode>;
    /**
     * 
     * @type {RepositoryGroundingSuccess}
     * @memberof FeatureListSystemMessageData
     */
    'repositoryGroundingCompletion'?: RepositoryGroundingSuccess;
}


