    /**
     * 
     * @type {TrackingEventMetadataViewport}
     * @memberof InitiativeEvent
     */
    'viewport': TrackingEventMetadataViewport;
    /**
     * 
     * @type {TrackingContext}
     * @memberof InitiativeEvent
     */
    'context': TrackingContext;
    /**
     * Event category identifier
     * @type {string}
     * @memberof InitiativeEvent
     */
    'category': InitiativeEventCategoryEnum;
    /**
     * 
     * @type {InitiativeAction}
     * @memberof InitiativeEvent
     */
    'action': InitiativeAction;
    /**
     * 
     * @type {InitiativeEventAllOfData}
     * @memberof InitiativeEvent
     */
