/**
 * Integration action types
 * @export
 * @enum {string}
 */

export const IntegrationAction = {
    Connect: 'connect',
    Disconnect: 'disconnect',
    Sync: 'sync',
    Import: 'import',
    Export: 'export',
    Webhook: 'webhook'
} as const;

export type IntegrationAction = typeof IntegrationAction[keyof typeof IntegrationAction];


/**
 * Connection health status of the integration. - CONNECTED: Integration is working properly - DISCONNECTED: Integration is not connected or authentication failed - ERROR: Integration encountered an error - PENDING: Initial connection attempt in progress - CONFIGURING: Integration is being set up 
 * @export
 * @enum {string}
 */

export const IntegrationConnectionStatus = {
    Connected: 'CONNECTED',
    Disconnected: 'DISCONNECTED',
    Error: 'ERROR',
    Pending: 'PENDING',
    Configuring: 'CONFIGURING'
} as const;

export type IntegrationConnectionStatus = typeof IntegrationConnectionStatus[keyof typeof IntegrationConnectionStatus];


