/**
 * Audit category for a machine security event. The first five are recorded by the CLI and reported to the server: signature_failure (a trigger envelope failed Ed25519 verification), replay_rejection (a duplicate/seen nonce), timestamp_window_rejection (an envelope outside the accepted clock-skew window), allowlist_rejection (a frame addressed to a machine/kind not on the allowlist), and rate_limit_trip (the CLI tripped its own inbound rate limiter). revocation is recorded server-side when the machine\'s credential is revoked; the CLI never reports it.
 * @export
 * @enum {string}
 */

export const MachineSecurityEventType = {
    SignatureFailure: 'signature_failure',
    ReplayRejection: 'replay_rejection',
    TimestampWindowRejection: 'timestamp_window_rejection',
    AllowlistRejection: 'allowlist_rejection',
    RateLimitTrip: 'rate_limit_trip',
    Revocation: 'revocation'
} as const;

export type MachineSecurityEventType = typeof MachineSecurityEventType[keyof typeof MachineSecurityEventType];


