/**
 * Payload for PHASE_GROUNDING reports — the forcing-function pre-flight a phase emits before it starts executing. Each entry in `touchPoints` names a file the phase intends to touch and the outcome it expects there; populating the array forces the agent to commit, in writing, to the concrete surface area of the upcoming work before it begins. The optional `planAdjustment` field captures a one-shot description of any change to the approved plan this grounding round implies — e.g. an added or dropped touch point that the plan did not anticipate. 
 * @export
 * @interface PhaseGroundingReportPayload
 */
export interface PhaseGroundingReportPayload {
    /**
     * 50-100 word phase handoff. Captures what the next agent needs to know to pick up — outcomes, decisions, and live constraints — not a turn-by-turn transcript of what happened this run. 
     * @type {string}
     * @memberof PhaseGroundingReportPayload
     */
    'summary': string;
    /**
     * 
     * @type {string}
     * @memberof PhaseGroundingReportPayload
     */
    'reportType': PhaseGroundingReportPayloadReportTypeEnum;
    /**
     * One entry per file the phase intends to touch. Must contain at least one item — the forcing-function contract requires the agent to name a concrete surface before the phase runs. 
     * @type {Array<PhaseGroundingReportTouchPoint>}
     * @memberof PhaseGroundingReportPayload
     */
    'touchPoints': Array<PhaseGroundingReportTouchPoint>;
    /**
     * Optional prose describing how this grounding round adjusts the prior approved plan (e.g. added/dropped touch points, scope shifts). Omitted when the grounding round matches the plan. 
     * @type {string}
     * @memberof PhaseGroundingReportPayload
     */
    'planAdjustment'?: string;
}

export const PhaseGroundingReportPayloadReportTypeEnum = {
    PhaseGrounding: 'PHASE_GROUNDING'
} as const;

export type PhaseGroundingReportPayloadReportTypeEnum = typeof PhaseGroundingReportPayloadReportTypeEnum[keyof typeof PhaseGroundingReportPayloadReportTypeEnum];

/**
 * One touch point an upcoming phase intends to land in: a specific file the agent will read or modify, paired with the outcome it expects there. `divergenceFromInitialPlan` is set only when this touch point differs from what the prior approved plan described — the absence of the field means the touch point matches the plan. 
 * @export
 * @interface PhaseGroundingReportTouchPoint
 */
export interface PhaseGroundingReportTouchPoint {
    /**
     * Repo-relative path of the file the phase expects to touch.
     * @type {string}
     * @memberof PhaseGroundingReportTouchPoint
     */
    'file': string;
    /**
     * Short prose describing what the agent expects to happen at this file — the contract it expects to find, the change it intends to make, or the behavior it expects to confirm. 
     * @type {string}
     * @memberof PhaseGroundingReportTouchPoint
     */
    'expectedOutcome': string;
    /**
     * When this touch point diverges from the prior approved plan, the short prose explanation of how and why. Omitted when the touch point matches the plan. 
     * @type {string}
     * @memberof PhaseGroundingReportTouchPoint
     */
    'divergenceFromInitialPlan'?: string;
}
