    'designDocId': string;
    /**
     * Canonical id of the plan being shaped. Included in the batched get_full_entity call so the agent can read the plan and its existing stage/step proposals to author or revise stage proposals against the live plan state. 
     * @type {string}
     * @memberof PlanShapingProposedStagesPromptPayload
     */
    'planId': string;
