/**
 * @type TaskMonitorAuthorityIncreasingCommand
 * Closed protocol-2 command set that may start, resume, continue, redirect, or complete host work. Its signed executable envelope supplies exactly one fresh controller assertion or matching controller-device grant reference.
 * @export
 */
export type TaskMonitorAuthorityIncreasingCommand = { cause: 'COMPLETE' } & TaskMonitorCompleteCommand | { cause: 'CONTINUE' } & TaskMonitorContinueCommand | { cause: 'JUDGMENT_RESOLVED' } & TaskMonitorJudgmentResolvedCommand | { cause: 'RESUME' } & TaskMonitorResumeCommand | { cause: 'START' } & TaskMonitorStartCommand;

/**
 * @type TaskMonitorAuthorityNeutralCommand
 * Authenticated user input that advances Task Monitor-owned state without directly starting, resuming, or terminating host execution.
 * @export
 */
export type TaskMonitorAuthorityNeutralCommand = { cause: 'GUIDANCE_CHANGED' } & TaskMonitorGuidanceChangedCommand | { cause: 'HUMAN_DECISION' } & TaskMonitorHumanDecisionCommand;

/**
 * @type TaskMonitorAuthorityNeutralRequestCommand
 * @export
 */
export type TaskMonitorAuthorityNeutralRequestCommand = { cause: 'GUIDANCE_CHANGED' } & TaskMonitorGuidanceChangedCommand | { cause: 'HUMAN_DECISION' } & TaskMonitorHumanDecisionRequestCommand;

/**
 * @type TaskMonitorAuthorityReductionCommand
 * Closed commands that only suspend or terminate authority. They do not carry or create controller execution authorization.
 * @export
 */
export type TaskMonitorAuthorityReductionCommand = { cause: 'HALT' } & TaskMonitorHaltCommand | { cause: 'PAUSE' } & TaskMonitorPauseCommand | { cause: 'STOP' } & TaskMonitorStopCommand;

