/**
 * Existing start-run semantic payload without browser authorization. The API admits the paired-machine proof and the originating Task Monitor command, then derives the bounded executable authorization from persisted state.
 * @export
 * @interface TaskMonitorRunEffectPayload
 */
export interface TaskMonitorRunEffectPayload {
    /**
     * Explicit replacement Run identity; the owning Agent Session is unchanged.
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'runId'?: string;
    /**
     * Optional file references for a handler launch. The CLI uses an empty list when omitted. Content stays on the host.
     * @type {Array<RunAttachmentReference>}
     * @memberof TaskMonitorRunEffectPayload
     */
    'attachments'?: Array<RunAttachmentReference>;
    /**
     * Shared Browser tab the user opened before the Run existed. The new Run adopts it as its selected page and its first Turn is told the user opened it and at which URL. Null when none. A reference whose tab no longer exists rejects the start with STAGED_BROWSER_TAB_NOT_FOUND before the first Turn. Turn-firing arm only. 
     * @type {StagedBrowserTabReference}
     * @memberof TaskMonitorRunEffectPayload
     */
    'stagedBrowserTab'?: StagedBrowserTabReference | null;
    /**
     * Whether the turn-firing arm fires turn one. Defaults to `true`: a `handlerPromptType` + `payload` envelope materializes the Run and immediately dispatches its first turn, exactly as before. When `false`, the CLI materializes the Run and binds `conversationId → runId` but fires no turn even though `handlerPromptType`/`payload` are present — the third, non-dispatching bootstrap mode, used to seed a standing SYSTEM greeting that simply waits for the user\'s first message. The non-workflow analogue of the `workflowName` materialize-only arm. Omit (or set `true`) on every existing turn-firing path. 
     * @type {boolean}
     * @memberof TaskMonitorRunEffectPayload
     */
    'triggersAgent'?: boolean;
    /**
     * The actual `LocalPromptType` routing key from the Agent Bridge contract that the CLI should dispatch the run against (e.g. `startup_session`, `feature_sync_analyze`, `implement`). Distinct from the sentinel `promptType: \'start_run\'` on the parent trigger envelope. Carried as a plain string because the `LocalPromptType` enum is owned by the transport-neutral Agent Bridge contract; the CLI narrows this string against its own enum at the dispatcher boundary. Present on the turn-firing arm only; absent when `workflowName` is set. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'handlerPromptType'?: string;
    /**
     * Typed prompt payload discriminated by `handlerPromptType`, refs the shared `RunCreatePayload` union in ./run-payloads.yaml — the same union that the Agent Bridge runtime validates, so the platform start-run envelope and CLI execution share one source of truth instead of an unconstrained re-validated object. Required with `handlerPromptType`, where it drives the first turn. Optional with `workflowName`: omitted for a bind-only workflow launch, or the `workflow_kickoff` variant for a kickoff launch. The API uses `userMessage` to author the opening USER row, and the CLI uses the optional canonical `entity` to materialize a scoped Run. Omitting `entity` from a kickoff payload represents a genuinely unscoped workflow launch. 
     * @type {RunCreatePayload}
     * @memberof TaskMonitorRunEffectPayload
     */
    'payload'?: RunCreatePayload;
    /**
     * Name of the Temporal workflow that orchestrates this session (e.g. `feature-sync`). Present on the materialize-only arm. When set, the CLI materializes the Run and binds the conversation but fires no first turn — the workflow drives every turn via its own SYSTEM triggers. Value-set mirrors the `WorkflowName` enum; carried as a plain string for the same independent-generation reason as `handlerPromptType`. `workflowName` is mutually exclusive with `handlerPromptType`. `payload` is absent for bind-only launches or must be the `workflow_kickoff` variant. For kickoff launches, the API authors the USER opening row from `payload.userMessage`; the CLI uses `payload.entity`, when present, as the Run\'s canonical focal identity. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'workflowName'?: string;
    /**
     * Claude model id the CLI should use for the run (e.g. `claude-opus-4-6`, `claude-sonnet-4-6`, `claude-haiku-4-5-20251001`). Forwarded verbatim onto the Agent Bridge runtime\'s model field. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'model': string;
    /**
     * Reasoning-effort level for the run. Value-set mirrors the Agent Bridge runtime contract (the source of truth); additions there require extending this enum in lockstep. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'reasoningEffort'?: TaskMonitorRunEffectPayloadReasoningEffortEnum;
    /**
     * Typed AgentSession launch config forwarded to the CLI. Project Assistant proactive behavior and plan-combination aggressiveness are read from this persisted config after the Run is materialized; absent config or absent flags resolve at the consuming boundary. 
     * @type {AgentSessionConfig}
     * @memberof TaskMonitorRunEffectPayload
     */
    'config'?: AgentSessionConfig | null;
    /**
     * Agent provider the CLI should dispatch against. Value-set mirrors the Agent Bridge runtime provider contract (the source of truth); additions there require extending this enum in lockstep. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'provider': TaskMonitorRunEffectPayloadProviderEnum;
    /**
     * 
     * @type {AgentSkillSelection}
     * @memberof TaskMonitorRunEffectPayload
     */
    'skillSelection'?: AgentSkillSelection;
    /**
     * Optional provider-neutral Fast mode preference. `true`, `false`, and omission are distinct; the provider runner decides how omission applies. This field is accepted only when `provider` is `codex` or `claude` and carries no provider-native value. 
     * @type {boolean}
     * @memberof TaskMonitorRunEffectPayload
     */
    'fastMode'?: boolean;
    /**
     * Run context metadata, refs the shared `RunContextMetadata` in the Agent Bridge-owned `RunContextMetadata` schema. The CLI adopts `agentSessionId` verbatim as the local run\'s `agentic_session_id` and stamps it on the `X-Agent-Session-ID` header for every MCP request. Shared so the platform start-run envelope and CLI execution validate against one source of truth instead of an unconstrained re-validated object. 
     * @type {RunContextMetadata}
     * @memberof TaskMonitorRunEffectPayload
     */
    'contextMetadata': RunContextMetadata;
    /**
     * Set of platform service ids the run executes against. Threaded through so the CLI can resolve working directories and scope without extra lookups. Optional: coding runs always carry it, but non-coding sessions (task / feature refiners, entity conversations) operate on entity text rather than a checked-out repo and omit it entirely. 
     * @type {Array<string>}
     * @memberof TaskMonitorRunEffectPayload
     */
    'serviceIds'?: Array<string>;
    /**
     * The service the CLI launches the session against. Required when serviceIds is non-empty; must be a member of serviceIds. Threaded through so the CLI can resolve the primary working directory without an extra lookup. Omit the field rather than sending an empty string. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'launchServiceId'?: string;
    /**
     * 
     * @type {StartRunWorktree}
     * @memberof TaskMonitorRunEffectPayload
     */
    'worktree'?: StartRunWorktree;
    /**
     * Canonical id of the platform agent session that owns this run. Mirrors `contextMetadata.agentSessionId` at the top level for symmetry with the context metadata\'s canonical session id. 
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'agentSessionId': string;
    /**
     * Fresh identity for one explicit user gesture. It is distinct from authorization, Message, Run, trigger-message, and delivery identities.
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'operationId': string;
    /**
     * Lowercase SHA-256 of the RFC 8785 canonical semantic request. The authorization envelope and operation metadata are excluded.
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'operationFingerprint': string;
    /**
     * Unique identifier for a paired machine (branded type)
     * @type {string}
     * @memberof TaskMonitorRunEffectPayload
     */
    'machineId': string;
}

