/**
 * A task within an organization. Polymorphic over TaskType; the same shape represents STANDARD, BUG, FEATURE, GOAL, DIAGRAM, DIAGRAM_ELEMENT, and TASK_MONITOR work items. GOAL tasks are top-level by definition (parentTaskId is always null) and may have no target date. GOAL tasks additionally carry `trackedEntities` — outgoing TRACKS-edge snapshots for the work the goal is tracking. Non-GOAL tasks omit the field or return an empty array. When requested, GOAL tasks also carry `trackedWorkSummary`, a compact count aggregate that is independent of the `trackedEntities` projection. FEATURE tasks carry `tag` (FeatureTag) classifying the feature; the field is absent on all non-FEATURE work-item types. 
 * @export
 * @interface TaskResponseDto
 */
export interface TaskResponseDto {
    /**
     * The unique identifier for the task.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'id': string;
    /**
     * The name or title of the task.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'name': string;
    /**
     * Work-item type key. Values are registry-backed and may include system keys such as `STANDARD`, `BUG`, `FEATURE`, `GOAL`, `PLAN`, `PLAN_STAGE`, `CONTRACT`, `DIAGRAM`, `DIAGRAM_ELEMENT`, and `TASK_MONITOR`, or project-defined keys created at runtime. 
     * @type {string}
     * @memberof TaskResponseDto
     */
    'type': string;
    /**
     * Typed launch defaults retained with the work item. Null or omission means no stored launch default; checkout materialization happens only when a coding session is started. 
     * @type {WorkItemConfigV1}
     * @memberof TaskResponseDto
     */
    'config'?: WorkItemConfigV1 | null;
    /**
     * 
     * @type {Array<MaterializedWorkItemSection>}
     * @memberof TaskResponseDto
     */
    'sections'?: Array<MaterializedWorkItemSection>;
    /**
     * The ID of the organization this task belongs to.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'organizationId': string;
    /**
     * The ID of the project this task belongs to.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'projectId': string;
    /**
     * The ID of the initiative this task is part of.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'initiativeId'?: string | null;
    /**
     * 
     * @type {WorkStatus}
     * @memberof TaskResponseDto
     */
    'status': WorkStatus;
    /**
     * 
     * @type {TaskSource}
     * @memberof TaskResponseDto
     */
    'source': TaskSource;
    /**
     * 
     * @type {TaskPriority}
     * @memberof TaskResponseDto
     */
    'priority'?: TaskPriority;
    /**
     * The target completion date, or null for an undated task.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'dueDate'?: string | null;
    /**
     * 
     * @type {FeatureTag}
     * @memberof TaskResponseDto
     */
    'tag'?: FeatureTag;
    /**
     * The ID of the user assigned to this task.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'assigneeId'?: string | null;
    /**
     * The ID of the user who reported or created this task.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'reporterId'?: string;
    /**
     * The ID of the parent task, if this is a sub-task.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'parentTaskId'?: string | null;
    /**
     * 
     * @type {TaskResponseDtoChildCounts}
     * @memberof TaskResponseDto
     */
    'childCounts'?: TaskResponseDtoChildCounts;
    /**
     * Number of design docs linked to this task. Present when includeDesignDocCounts=true; otherwise null.
     * @type {number}
     * @memberof TaskResponseDto
     */
    'designDocCount'?: number | null;
    /**
     * Number of coding sessions (type=CODING) linked to this task. Present when includeAgentSessionCounts=true; otherwise null.
     * @type {number}
     * @memberof TaskResponseDto
     */
    'codingSessionCount'?: number | null;
    /**
     * Number of non-coding agent sessions (e.g. DAILY_SESSION, TASK_REFINING) linked to this task. Present when includeAgentSessionCounts=true; otherwise null.
     * @type {number}
     * @memberof TaskResponseDto
     */
    'agentSessionCount'?: number | null;
    /**
     * Service-to-task relation records linked to this task. Present when includeServiceRelations=true.
     * @type {Array<ServiceTaskRelation>}
     * @memberof TaskResponseDto
     */
    'serviceRelations'?: Array<ServiceTaskRelation>;
    /**
     * Agent-authored graph edges that touch this task (inbound + outbound, deduplicated by edge id). Present when includeEdges=true on the request; otherwise omitted. When `edgeTypes` is omitted, the response uses the default generic edge label set; when `edgeTypes` is provided, the requested AgentEdgeType labels define the returned edge domain. Edges can include workflow labels (`STANDARD`, `CONDITIONAL`, `LOOP`, `FULFILLED_BY`) and preserve graph relationship metadata such as category, direction, and predicate. 
     * @type {Array<AgentEdgeResponseDto>}
     * @memberof TaskResponseDto
     */
    'edges'?: Array<AgentEdgeResponseDto>;
    /**
     * The timestamp when the task was created.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'createdAt'?: string;
    /**
     * The timestamp when the task was last updated.
     * @type {string}
     * @memberof TaskResponseDto
     */
    'updatedAt'?: string;
    /**
     * Whether this entity type supports MCP proposal tools (e.g. edit_task). Always true for tasks.
     * @type {boolean}
     * @memberof TaskResponseDto
     */
    'hasProposalSupport'?: boolean;
    /**
     * The timestamp when the task was archived (soft delete).
     * @type {string}
     * @memberof TaskResponseDto
     */
    'archivedAt'?: string | null;
    /**
     * Outgoing `TRACKS` edges from this task, inlined as snapshots so list views render tracked items without a second hop. Populated only for GOAL-typed tasks (other task types omit the field or return an empty array). Order is unspecified; callers should not rely on it. 
     * @type {Array<TrackedEntitySnapshot>}
     * @memberof TaskResponseDto
     */
    'trackedEntities'?: Array<TrackedEntitySnapshot>;
    /**
     * 
     * @type {GoalTrackedWorkSummary}
     * @memberof TaskResponseDto
     */
    'trackedWorkSummary'?: GoalTrackedWorkSummary;
}


